import { stat } from 'node:fs/promises'
import path from 'node:path'
import { cache } from 'react'
import { hasFirebaseConfig } from '@/lib/firebase/client'
import { getContentDocument } from '@/lib/firebase/content-services'
import {
  DOWNLOADS_ID,
  defaultDownloadsContent,
  normalizeDownloadsContent,
  type DownloadGroup,
  type DownloadItem,
  type DownloadsContent,
} from '@/lib/downloads'
import type { DownloadsDocument } from '@/types/firestore'

/*
 * Isi /unduhan untuk halaman publik: daftar dari Firestore, ukuran dari disk.
 *
 * Dua sumber, dan pembagiannya bukan kebetulan.
 *
 * Daftarnya milik pengurus, jadi ia tinggal di Firestore dan disunting lewat
 * /admin/downloads. Ukuran berkas BUKAN milik siapa pun untuk diketik: angka
 * yang ditulis tangan selalu jadi salah pada unggahan berikutnya, dan "4,8 MB"
 * yang ternyata 12 MB adalah kebohongan kecil yang persis mengenai orang
 * berkuota tipis. Jadi ukuran dibaca dari berkas yang benar-benar akan dikirim.
 *
 * Efek sampingnya yang paling berguna: berkas lokal yang belum ada TIDAK bisa
 * tampil sebagai tautan. `stat` gagal, barisnya turun jadi slot "Menyusul", dan
 * halaman ini secara struktural tidak bisa memuat tautan mati ke public/.
 *
 * HANYA untuk server, dan itu bukan anjuran. Berkas ini mengimpor node:fs, dan
 * webpack tidak bisa menyelesaikan skema `node:` untuk bundle browser: satu
 * impor dari komponen klien menggagalkan seluruh halaman yang memuatnya.
 * Tetapan yang dibutuhkan kedua sisi — DOWNLOADS_ID — karena itu tinggal di
 * src/lib/downloads.ts yang murni, bukan di sini.
 */

export type ResolvedDownload = DownloadItem & {
  available: boolean
  /** Sudah diformat untuk dibaca manusia, mis. '4,8 MB'. Hanya untuk `file`. */
  size?: string
}

export type ResolvedDownloadGroup = Omit<DownloadGroup, 'items'> & {
  items: ResolvedDownload[]
  readyCount: number
}

export type ResolvedDownloads = Omit<DownloadsContent, 'groups'> & {
  groups: ResolvedDownloadGroup[]
}

/**
 * Ukuran berkas dalam satuan biner, ditulis dengan koma desimal.
 *
 * Ambang satu desimal dipasang di 10: "9,8 MB" masih berguna, "128,4 KB"
 * ketelitian yang tidak dipakai siapa pun.
 */
export function formatFileSize(bytes: number): string {
  const units = ['B', 'KB', 'MB', 'GB']
  let value = bytes
  let unit = 0

  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit += 1
  }

  const rounded = value < 10 && unit > 0 ? Math.round(value * 10) / 10 : Math.round(value)

  return `${rounded.toString().replace('.', ',')} ${units[unit]}`
}

/**
 * Path berkas di disk untuk sebuah href publik.
 *
 * Menolak apa pun yang keluar dari public/, termasuk href yang mengandung '..'.
 * Isian ini sekarang datang dari panel, bukan dari berkas kode, jadi
 * pemeriksaannya berhenti jadi kehati-hatian dan mulai jadi syarat: satu akun
 * editor tidak boleh bisa membuat server membaca berkas di luar public/.
 */
function resolvePublicPath(href: string): string | null {
  if (!href.startsWith('/')) {
    return null
  }

  const publicRoot = path.join(process.cwd(), 'public')
  const target = path.join(publicRoot, decodeURIComponent(href))
  const relative = path.relative(publicRoot, target)

  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    return null
  }

  return target
}

async function resolveItem(item: DownloadItem): Promise<ResolvedDownload> {
  if (!item.href) {
    return { ...item, available: false }
  }

  if (item.kind === 'link') {
    return { ...item, available: /^https?:\/\//i.test(item.href) }
  }

  const filePath = resolvePublicPath(item.href)
  if (!filePath) {
    return { ...item, available: false }
  }

  try {
    const stats = await stat(filePath)
    if (!stats.isFile()) {
      return { ...item, available: false }
    }

    return { ...item, available: true, size: formatFileSize(stats.size) }
  } catch {
    return { ...item, available: false }
  }
}

/**
 * Isi mentah dari Firestore, atau bawaan.
 *
 * Selalu berhasil, dengan alasan yang sama seperti getSiteSettings: halaman
 * unduhan yang menampilkan daftar bawaan jauh lebih baik daripada halaman yang
 * gagal dirender gara-gara satu dokumen tidak terbaca.
 */
export const getDownloadsContent = cache(async function getDownloadsContent(): Promise<DownloadsContent> {
  if (!hasFirebaseConfig()) {
    return defaultDownloadsContent
  }

  try {
    const document = await getContentDocument<DownloadsDocument>('downloads', DOWNLOADS_ID)
    return normalizeDownloadsContent(document as Record<string, unknown> | null)
  } catch (error) {
    console.warn('[downloads] Gagal membaca downloads/index, memakai daftar bawaan.', error)
    return defaultDownloadsContent
  }
})

/**
 * Isi halaman lengkap, sudah disaring visibilitasnya dan sudah tahu ukuran
 * tiap berkas.
 *
 * Kelompok dan berkas yang disembunyikan pengurus dibuang DI SINI, bukan di
 * komponen. Kalau penyaringannya dikerjakan saat merender, satu tempat yang
 * lupa menyaring cukup untuk membocorkan berkas yang sengaja disembunyikan.
 */
export async function getResolvedDownloads(): Promise<ResolvedDownloads> {
  const content = await getDownloadsContent()

  const groups = await Promise.all(
    content.groups
      .filter((group) => group.visible)
      .map(async (group) => {
        const items = await Promise.all(
          group.items.filter((item) => item.visible).map(resolveItem),
        )

        return {
          ...group,
          items,
          readyCount: items.filter((item) => item.available).length,
        }
      }),
  )

  // Kelompok yang seluruh isinya disembunyikan tidak menyisakan judul yang
  // menggantung di atas ruang kosong.
  return { ...content, groups: groups.filter((group) => group.items.length > 0) }
}

/** Semua berkas dari semua kelompok, diratakan, untuk menghitung dan mencari plat. */
export function flattenDownloads(groups: ResolvedDownloadGroup[]): ResolvedDownload[] {
  return groups.flatMap((group) => group.items)
}
