import type { Metadata } from 'next'
import Image from 'next/image'
import Link from 'next/link'
import { HeroBackdrop } from '@/components/site/HeroBackdrop'
import { PublicPageFrame } from '@/components/site/PublicPage'
import {
  flattenDownloads,
  getResolvedDownloads,
  type ResolvedDownload,
} from '@/lib/downloads-data'
import { getSiteSettings } from '@/lib/site-settings-data'

/*
 * Jaring pengaman, bukan jalur utama.
 *
 * Jalur normalnya panel memanggil /api/revalidate begitu daftar berkas berubah,
 * jadi halaman ini segar dalam hitungan detik. `revalidate` di bawah ini yang
 * menangkapnya kalau panggilan itu gagal — dan sekaligus memunculkan berkas
 * yang baru ditaruh di public/assets/unduhan/ tanpa perlu menyimpan apa pun di
 * panel, karena ukuran dan ketersediaannya dibaca dari disk saat render.
 */
export const revalidate = 300

export const metadata: Metadata = {
  title: 'Unduhan HMTE TRE SV UGM',
  description:
    'Lambang HMTE, logo Kabinet Abya Vistara, dokumen organisasi, dan template kegiatan dalam satu tempat.',
}

/*
 * /unduhan — loket berkas.
 *
 * Halaman ini punya dua wajah karena melayani dua kebiasaan yang berbeda.
 *
 * Yang pertama LOKET IDENTITAS: orang yang datang mencari logo tidak tahu nama
 * berkasnya, ia mengenali bentuknya. Jadi berkas gambar yang ditandai pengurus
 * sebagai "plat" dipasang besar-besar di atas latar tempat ia memang dipakai,
 * dan tombolnya menempel di gambarnya sendiri.
 *
 * Yang kedua RAK DOKUMEN: orang yang datang mencari template sudah tahu apa
 * yang dicarinya dan cuma ingin cepat. Jadi sisanya baris padat: format, nama,
 * keterangan satu baris, ukuran, unduh.
 *
 * Satu aturan yang mengikat: baris yang berkasnya belum ada tidak disembunyikan.
 * Ia tampil sebagai slot bertanda "Menyusul". Menyembunyikannya membuat halaman
 * terlihat lebih rapi hari ini dengan menukar sesuatu yang lebih berharga, yaitu
 * pengunjung jadi tahu berkas itu memang direncanakan ada dan tidak perlu
 * mencarinya ke tempat lain. Yang benar-benar tidak ingin ditampilkan pengurus
 * punya saklarnya sendiri di panel, dan yang itu memang hilang sama sekali.
 */
export default async function DownloadsPage() {
  const [content, settings] = await Promise.all([getResolvedDownloads(), getSiteSettings()])

  const all = flattenDownloads(content.groups)
  const readyCount = all.filter((item) => item.available).length
  const pendingCount = all.length - readyCount

  /*
   * Plat diturunkan dari berkasnya sendiri, bukan dari daftar terpisah.
   *
   * Versi pertama memakai konstanta `brandPlates` yang menunjuk id berkas. Itu
   * sanggup hidup selama daftarnya ada di berkas kode; begitu pengurus bisa
   * mengganti id lewat panel, daftar itu berubah jadi acuan menggantung yang
   * diam-diam berhenti cocok. Sekarang tiap berkas membawa sendiri keterangan
   * "aku dipratinjau di atas latar apa".
   */
  const plates = all.filter((item) => item.preview !== 'none' && item.available)

  return (
    <PublicPageFrame activeHref="/unduhan">
      <section className="soft-surface" aria-labelledby="downloads-title">
        <div className="soft-shell">
          <header className="dl-lead has-hero-backdrop">
            <HeroBackdrop variant="dome" />
            <div className="dl-lead-copy">
              <p className="dl-lead-kicker">
                {content.heroKicker} · Kabinet {settings.cabinetName}
              </p>
              <h1 id="downloads-title">
                {content.heroTitle}{' '}
                {content.heroHighlight ? <span>{content.heroHighlight}</span> : null}
              </h1>
              <p className="dl-lead-note">{content.heroLead}</p>
            </div>
            <dl className="dl-lead-stats">
              <div>
                <dt>Siap unduh</dt>
                <dd>{readyCount}</dd>
              </div>
              <div>
                <dt>Menyusul</dt>
                <dd>{pendingCount}</dd>
              </div>
            </dl>
          </header>

          {plates.length > 0 ? (
            <section className="dl-plates" aria-labelledby="brand-title">
              <div className="dl-section-head">
                <h2 id="brand-title">{content.brandTitle}</h2>
                {content.brandLead ? <p>{content.brandLead}</p> : null}
              </div>

              <div className="dl-plate-grid">
                {plates.map((item, index) => (
                  <figure className="dl-plate" key={item.id} data-tone={item.preview}>
                    <div className="dl-plate-stage">
                      {/*
                        Pratinjau dilewatkan pengoptimal, berkas unduhannya tidak.
                        Logo kabinet aslinya 4,8 MB dan di sini digambar selebar
                        270px; mengirim berkas mentahnya ke setiap pengunjung
                        hanya supaya pratinjaunya "berkas yang asli" adalah
                        mahal untuk sesuatu yang tidak bisa dilihat bedanya.
                        Yang diunduh tombol di bawahnya tetap berkas aslinya.

                        SVG dikecualikan: pengoptimal Next menolak SVG kecuali
                        dangerouslyAllowSVG dinyalakan, dan menyalakannya untuk
                        satu gambar berarti mengizinkan SVG dari mana pun.
                      */}
                      <Image
                        src={item.href}
                        alt={`Pratinjau ${item.name}`}
                        width={320}
                        height={200}
                        sizes="(max-width: 780px) 100vw, 320px"
                        unoptimized={item.href.toLowerCase().endsWith('.svg')}
                        // Yang pertama di atas lipatan pada layar lebar, dan
                        // plat-plat inilah isi utama halaman ini.
                        priority={index === 0}
                      />
                    </div>
                    <figcaption>
                      <strong>{item.name}</strong>
                      {item.desc ? <p>{item.desc}</p> : null}
                      <a className="dl-plate-get" href={item.href} download>
                        <span>Unduh {item.format}</span>
                        {item.size ? <em>{item.size}</em> : null}
                        <svg
                          width="15"
                          height="15"
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          aria-hidden="true"
                        >
                          <path d="M12 4v12m0 0 5-5m-5 5-5-5M5 20h14" />
                        </svg>
                      </a>
                    </figcaption>
                  </figure>
                ))}
              </div>

              {content.rules.length > 0 ? (
                <aside className="dl-rules">
                  <h3>{content.rulesTitle}</h3>
                  <ol>
                    {content.rules.map((rule) => (
                      <li key={rule}>{rule}</li>
                    ))}
                  </ol>
                </aside>
              ) : null}
            </section>
          ) : null}

          {content.groups.map((group) => (
            <section className="dl-group" key={group.id} aria-labelledby={`group-${group.id}`}>
              <div className="dl-section-head">
                <h2 id={`group-${group.id}`}>{group.title}</h2>
                {group.lead ? <p>{group.lead}</p> : null}
              </div>

              <ul className="dl-rows">
                {group.items.map((item) => (
                  <li key={item.id}>
                    <DownloadRow item={item} />
                  </li>
                ))}
              </ul>
            </section>
          ))}

          <aside className="dl-ask">
            <div>
              <h2>{content.askTitle}</h2>
              <p>{content.askBody}</p>
            </div>
            <div className="dl-ask-actions">
              <Link className="dl-ask-primary" href="/kontak">
                Hubungi pengurus
              </Link>
              <Link className="dl-ask-secondary" href="/aspirasi">
                Kirim lewat aspirasi
              </Link>
            </div>
          </aside>
        </div>
      </section>
    </PublicPageFrame>
  )
}

/*
 * Satu baris berkas.
 *
 * Baris yang siap adalah <a download>, baris yang belum ada adalah <div>. Bukan
 * tautan yang dinonaktifkan: tautan mati yang terlihat seperti tautan hidup akan
 * diklik, dan tiap kliknya adalah janji yang tidak ditepati.
 */
function DownloadRow({ item }: { item: ResolvedDownload }) {
  const body = (
    <>
      <span className="dl-format" aria-hidden="true">
        {item.format}
      </span>
      <span className="dl-row-copy">
        <strong>{item.name}</strong>
        {item.desc ? <small>{item.desc}</small> : null}
      </span>
      <span className="dl-row-meta">
        {item.note ? <em>{item.note}</em> : null}
        {item.available ? (
          <b>{item.kind === 'link' ? 'Tautan luar' : item.size}</b>
        ) : (
          <b className="dl-soon">Menyusul</b>
        )}
      </span>
    </>
  )

  if (!item.available) {
    return (
      <div className="dl-row" data-state="soon">
        {body}
        <span className="sr-only">Berkas belum tersedia</span>
      </div>
    )
  }

  if (item.kind === 'link') {
    return (
      <a className="dl-row" href={item.href} target="_blank" rel="noopener noreferrer">
        {body}
        <span className="dl-row-go" aria-hidden="true">
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M7 17 17 7M9 7h8v8" />
          </svg>
        </span>
        <span className="sr-only">Membuka di tab baru</span>
      </a>
    )
  }

  return (
    <a className="dl-row" href={item.href} download>
      {body}
      <span className="dl-row-go" aria-hidden="true">
        <svg
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M12 4v12m0 0 5-5m-5 5-5-5M5 20h14" />
        </svg>
      </span>
    </a>
  )
}
